import{_ as t,o as n,c as i,a3 as o}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"Manage columns","description":"Hide, reorder, and lock columns in a view.","frontmatter":{"title":"Manage columns","description":"Hide, reorder, and lock columns in a view."},"headers":[],"relativePath":"en/ansichten/spalten-verwalten.md","filePath":"en/ansichten/spalten-verwalten.md","lastUpdated":1787319236000}'),a={name:"en/ansichten/spalten-verwalten.md"};function s(r,e,l,d,c,h){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="manage-columns" tabindex="-1">Manage columns <a class="header-anchor" href="#manage-columns" aria-label="Permalink to &quot;Manage columns&quot;">​</a></h1><p>Which columns appear and in what order is set <strong>per view</strong>. Other views of the same Grid remain unaffected.</p><div class="warning custom-block"><p class="custom-block-title">Hiding isn&#39;t deleting</p><p>A hidden column is only invisible in this view. The data remains fully intact and is present in every other view.</p><p>Deleting a column, on the other hand, removes the values from <strong>all</strong> entries — permanently.</p></div><h2 id="hiding-columns" tabindex="-1">Hiding columns <a class="header-anchor" href="#hiding-columns" aria-label="Permalink to &quot;Hiding columns&quot;">​</a></h2><ol><li>Click <strong>Hide</strong> in the toolbar.</li><li>Toggle off individual columns.</li></ol><p>When columns are hidden, the toolbar shows this as <strong>hidden</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Views for different tasks</p><p>Instead of horizontally scrolling one wide table, several views with matching column sets pay off — &quot;Editing&quot; with all fields, &quot;Overview&quot; with four columns, &quot;For export&quot; with exactly the fields that should go into the CSV.</p></div><h2 id="reordering-columns" tabindex="-1">Reordering columns <a class="header-anchor" href="#reordering-columns" aria-label="Permalink to &quot;Reordering columns&quot;">​</a></h2><p>Via <strong>More</strong> (⋮) → <strong>Rearrange columns</strong>. The hint reads <em>Reorder columns via drag and drop</em>.</p><div class="tip custom-block"><p class="custom-block-title">Put what matters on the left</p><p>The first two or three columns are what users see first — and in an embedded <a href="/en/seiten/portal-veroeffentlichen">portal</a> on narrow screens, sometimes the only thing they see. Put whatever identifies the entry there.</p></div><h2 id="locking-columns" tabindex="-1">Locking columns <a class="header-anchor" href="#locking-columns" aria-label="Permalink to &quot;Locking columns&quot;">​</a></h2><p>Via the menu in the column header: <strong>Lock column in this view</strong>. The column then shows the notice <em>Column is locked in this view</em>; use <strong>Unlock column in this view</strong> to undo it.</p><p>A locked column is visible, but can&#39;t be edited in this view.</p><div class="tip custom-block"><p class="custom-block-title">What locking is good for</p><p>For views used by other people who shouldn&#39;t change certain fields — for example, a shared view where prices should be visible but not editable.</p><p><strong>This is not access control</strong>, but a safeguard against mistakes: the lock applies per view, and anyone who opens a different view can edit the field there. For actual restrictions, use <a href="/en/zusammenarbeit/rollen">roles</a> and <a href="/en/zusammenarbeit/zugriff-beschraenken">access restrictions</a>.</p></div><h2 id="renaming-and-describing-a-column" tabindex="-1">Renaming and describing a column <a class="header-anchor" href="#renaming-and-describing-a-column" aria-label="Permalink to &quot;Renaming and describing a column&quot;">​</a></h2><p>Via the menu in the column header:</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Edit field</strong></td><td>Opens <strong>column name</strong> and <strong>column type</strong></td></tr><tr><td><strong>Edit column description</strong></td><td>Explanatory text for the field</td></tr><tr><td><strong>Manage field key</strong></td><td>Technical identifier of the field</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Name and type apply to the entire Grid</p><p>Unlike hiding and sorting, these changes apply <strong>everywhere</strong> — in every view, form, and flow.</p><p>Renaming is uncritical, since names aren&#39;t referenced internally. Changing the type, on the other hand, can lose values. → <a href="/en/grids/grid-anlegen">Your first Grid</a></p></div><div class="tip custom-block"><p class="custom-block-title">Descriptions save follow-up questions</p><p>The column description also appears in <a href="/en/formulare/felder-konfigurieren">forms</a> as help text beneath the field. A sentence about &quot;what goes here&quot; noticeably reduces bad input — especially for fields other people fill in.</p></div><h2 id="sum-row" tabindex="-1">Sum row <a class="header-anchor" href="#sum-row" aria-label="Permalink to &quot;Sum row&quot;">​</a></h2><p>Below numeric columns you can display a <strong>sum</strong> across all visible entries. It respects the active filter.</p><p>Available for <strong>Number</strong>, <strong>Decimal</strong>, and <strong>Currency</strong>.</p><h2 id="customizing-the-empty-view" tabindex="-1">Customizing the empty view <a class="header-anchor" href="#customizing-the-empty-view" aria-label="Permalink to &quot;Customizing the empty view&quot;">​</a></h2><p>Via <strong>More</strong> (⋮) → <strong>Edit empty view</strong>, you change the text that appears when no entries are visible — the default is <em>No results found</em>.</p><div class="tip custom-block"><p class="custom-block-title">Useful in portals</p><p>In a published portal, &quot;No results found&quot; isn&#39;t very helpful. A text like &quot;No bookings for this period yet&quot; explains to visitors what&#39;s going on.</p></div><p>→ <a href="/en/ansichten/leerzustand">Customizing the empty state</a></p><h2 id="what-else-belongs-to-the-view" tabindex="-1">What else belongs to the view <a class="header-anchor" href="#what-else-belongs-to-the-view" aria-label="Permalink to &quot;What else belongs to the view&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Applies to</th></tr></thead><tbody><tr><td>Hidden columns, order, locks</td><td>this view only</td></tr><tr><td>Empty state text</td><td>this view only</td></tr><tr><td>Column name, type, description, field key</td><td>the entire Grid</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></li><li><a href="/en/ansichten/ansicht-teilen">Sharing a view</a></li><li><a href="/en/referenz/spaltentypen">Column type reference</a></li></ul>',30)])])}const m=t(a,[["render",s]]);export{p as __pageData,m as default};
